"""M20 supplied references 19–27, retaining mechanisms, calculations and caveats."""

def foundations(Body):
 b=Body()
 b.p('本部分對應原始第 19–27 題，從 M20 對稱／非對稱加密到數位簽章。目標是建立可解變形題的原理，不只背 AES、RSA、DSA 或 Twofish 名稱。','This part covers supplied references 19–27, from M20 symmetric/asymmetric cryptography to signatures. The objective is reasoning that transfers to reworded questions, rather than memorizing names such as AES, RSA, DSA or Twofish.')
 b.p('銀行傳送一筆新臺幣 10 萬元交易，可能同時要求不被偷看、不被改成 100 萬元、確認來源為可信銀行，以及安全建立通訊金鑰。單一演算法不會自動完成這四件事。','A bank transmitting an NT$100,000 transaction may need to prevent reading, prevent alteration to NT$1,000,000, authenticate a trusted bank source and establish communication keys securely. One algorithm does not automatically accomplish all four.')
 b.h('p3-crypto-map','1. 密碼學的四類工作','1. Four cryptographic jobs')
 b.table([['工具類別','解決問題','例子'],['Encryption｜加密','防止未授權偷看','AES、Twofish、RSA 加密方案'],['Key Establishment｜金鑰建立','雙方如何取得共同秘密','DH、ECDH、RSA-based schemes'],['Hash｜雜湊','產生資料指紋','SHA-256、SHA-3'],['Digital Signature｜數位簽章','來源與完整性證據','RSA-PSS、ECDSA、EdDSA、傳統 DSA']],
         [['Category','Problem','Examples'],['Encryption','Prevent unauthorized reading','AES, Twofish and RSA encryption schemes'],['Key establishment','Obtain shared secret material','DH, ECDH and RSA-based schemes'],['Hashing','Produce a data fingerprint','SHA-256 and SHA-3'],['Digital signature','Evidence of origin and integrity','RSA-PSS, ECDSA, EdDSA and traditional DSA']])
 b.p('四類並列於「保護資訊與建立可信通訊」的密碼學主幹，不是四個必經順序；之後將各演算法放回其工作位置。','These four categories share the purpose of protecting information and enabling trusted communication. They are not four mandatory sequential stages. Place each algorithm according to its job.')
 b.h('p3-six-terms','2. 六個基本術語','2. Six foundational terms')
 b.p('Transfer NT$100,000 to Account B 是銀行要傳送的原始指令。','Transfer NT$100,000 to Account B is the bank’s original instruction.')
 b.table([['術語','中文','意義'],['Plaintext','明文','原本可理解資料'],['Ciphertext','密文','加密後無法直接理解原內容的資料'],['Encryption','加密','明文轉密文'],['Decryption','解密','以適當金鑰與程序還原'],['Algorithm','演算法','規定資料如何運算、轉換'],['Cryptographic Key','密碼學金鑰','控制運算的秘密值或相關材料']],
         [['Term','Meaning','Explanation'],['Plaintext','Readable original','Data before encryption'],['Ciphertext','Encrypted representation','Data whose original content cannot be read directly'],['Encryption','Encrypt','Transform plaintext into ciphertext'],['Decryption','Decrypt','Recover data with an appropriate key and procedure'],['Algorithm','Defined procedure','Specifies mathematical operations and transformations'],['Cryptographic key','Key material','Secret values or related material controlling the operation']])
 b.p('演算法像保險箱鎖具機構，金鑰像鑰匙。演算法通常公開，秘密金鑰才需保密；現代密碼學不應只靠藏住演算法。','An algorithm resembles the safe’s lock mechanism; a key resembles its key. Algorithms are commonly public, while secret keys need confidentiality. Modern cryptography should not depend only on concealing the algorithm.')
 b.h('p3-bits-encryption','3. 從位元到密文','3. From bits to ciphertext')
 b.p('Bit 只有 0 或 1，8 bits 組成一 Byte；ASCII 字母 A 可表示為 01000001。加密依金鑰執行設計過的數學轉換。','A bit is 0 or 1, and 8 bits form a byte. ASCII A can be represented as 01000001. Encryption applies designed mathematical transformations controlled by a key.')
 b.table([['階段','示意'],['明文','Transfer NT$100,000'],['加密','例如 AES-256 加上秘密金鑰與適當程序'],['密文','7F 2A 91 C0 5B ...（示意，非實際 AES 結果）'],['解密','正確金鑰與解密程序'],['還原','Transfer NT$100,000']],
         [['Stage','Illustration'],['Plaintext','Transfer NT$100,000'],['Encrypt','For example, AES-256 with a secret key and suitable procedure'],['Ciphertext','7F 2A 91 C0 5B ... (illustrative, not an actual AES result)'],['Decrypt','The correct key and decryption procedure'],['Recovery','Transfer NT$100,000']])
 b.p('Base64 與十六進位是公開可逆的表示方式，不是秘密加密。實際密碼系統另需運作模式、初始化資料、金鑰管理與錯誤處理；只說「AES-256」不足以證明系統安全。','Base64 and hexadecimal are publicly reversible representations, not secret encryption. Real cryptosystems also require modes, initialization data, key management and error handling. Saying “AES-256” alone does not establish system security.')
 return b.text

def symmetric(Body):
 b=Body()
 b.p('對應第 19、21 題。分清共享秘密、區塊長度、金鑰長度，再看 AES 選拔歷史。','References 19 and 21. Distinguish shared secrets, block size and key size, then examine AES selection history.')
 b.h('p3-symmetric-principle','1. Symmetric Encryption','1. Symmetric encryption')
 b.p('Alice 用一把鑰匙鎖箱子，Bob 用同一把鑰匙開啟：Alice 加密 → 共享秘密金鑰 K → Bob 解密。AES 與 Twofish 屬這一類，通常高效率、適合大量資料；難點是雙方須先安全取得共同秘密。','Alice locks a box with a key and Bob opens it using the same key: Alice encrypts → shared secret key K → Bob decrypts. AES and Twofish belong to this category. They are generally efficient for bulk data, but both parties must first obtain the common secret safely.')
 b.h('p3-block','2. Block Cipher 的固定單位','2. The fixed unit of a block cipher')
 b.p('Cipher 是密碼演算法，Block 是資料區塊。像工廠機器每次處理 16 個小盒子，即使總數上千，單次基本單位仍為 16。128-bit 區塊 = 128 ÷ 8 = 16 bytes；不是整份檔案限 16 bytes，長資料需用適當 Mode of Operation 處理多區塊。','Cipher means a cryptographic algorithm and block means a data unit. A factory machine handling 16 small boxes at once still uses that unit when processing thousands. A 128-bit block is 128 ÷ 8 = 16 bytes. It does not limit an entire file to 16 bytes; a suitable mode handles longer data across blocks.')
 b.h('p3-size','3. Key Size 不等於 Block Size','3. Key size is not block size')
 b.p('題目 operates on 128-bit blocks, accepts keys up to 256 bits 表示兩個參數：區塊 128 bits = 16 bytes；金鑰 256 bits = 32 bytes。NIST FIPS 197 的 AES-128／192／256 均用 128-bit 區塊，因此這組數字不能唯一識別 Twofish。','Operates on 128-bit blocks, accepts keys up to 256 bits describes two parameters: a 128-bit/16-byte block and a 256-bit/32-byte key. AES-128, AES-192 and AES-256 in NIST FIPS 197 all retain a 128-bit block. These values therefore cannot uniquely identify Twofish.')
 b.h('p3-stream','4. Stream Cipher 與 Keystream','4. Stream ciphers and keystreams')
 b.table([['特性','Block Cipher','Stream Cipher'],['處理方式','固定大小區塊轉換','產生金鑰串流與資料逐位元／位元組結合'],['例子','AES、Twofish、Blowfish','RC4、ChaCha20'],['題目線索','Block Size','Keystream'],['實務條件','正確模式','正確 Nonce 與串流使用規則']],
         [['Property','Block cipher','Stream cipher'],['Processing','Transform fixed-size blocks','Generate a keystream combined with data bits/bytes'],['Examples','AES, Twofish, Blowfish','RC4, ChaCha20'],['Question clue','Block size','Keystream'],['Usage requirements','Correct mode','Correct nonce and keystream-use rules']])
 b.p('Keystream 是依秘密金鑰等輸入產生的位元串流。第 19 題明確給 128-bit block，即可排除不是固定區塊演算法的 RC4。','A keystream is a bit stream generated from a secret key and related inputs. An explicit 128-bit block in reference 19 excludes RC4, which is not a fixed-block cipher.')
 b.h('p3-aes-history','5. Twofish 與 AES 選拔','5. Twofish and the AES selection')
 b.p('DES 因金鑰短等問題逐漸不符需求，NIST 公開評選新對稱標準。五個決選者是並列候選，不是五步流程：','DES no longer met evolving needs because of issues including its short key. NIST held a public selection for a new symmetric standard. The five finalists were parallel candidates, not five process stages:')
 b.table([['決選演算法','結果'],['MARS','決選者，未獲選'],['RC6','決選者，未獲選'],['Serpent','決選者，未獲選'],['Twofish','決選者，未獲選'],['Rijndael','獲選，成為 AES 採用的設計']],
         [['Finalist','Outcome'],['MARS','Finalist, not selected'],['RC6','Finalist, not selected'],['Serpent','Finalist, not selected'],['Twofish','Finalist, not selected'],['Rijndael','Selected as the design used for AES']])
 b.p('依 NIST《Report on the Development of the AES》：Twofish 像決賽選手，Rijndael 才是冠軍。問「未獲選的決選者」可答 Twofish；問「最後獲選」是 Rijndael；只問「曾進決選」則 Twofish 與 Rijndael 都符合。','NIST’s Report on the Development of the AES distinguishes finalist Twofish from winner Rijndael. A nonselected finalist can be Twofish; the selected algorithm is Rijndael. Merely asking who reached the final includes both.')
 b.h('p3-q19-q21','6. 第 19、21 題的預期與歧義','6. Expected answers and ambiguity in references 19 and 21')
 b.table([['題號','供稿選項','預期答案'],['19. EC-Q493','A RC4、B AES、C Blowfish、D Twofish','D'],['21. P1-Q114','A Blowfish、B Twofish、C RC4、D AES','B']],
         [['Reference','Supplied options','Expected answer'],['19. EC-Q493','A RC4, B AES, C Blowfish, D Twofish','D'],['21. P1-Q114','A Blowfish, B Twofish, C RC4, D AES','B']])
 b.p('兩題只換排序。128-bit block 排除 RC4 與 64-bit Blowfish，剩 AES／Twofish。出題者預期「決選但未獲選」的 Twofish，所以答案 D／B；但題幹未明說「未獲選」，嚴格無法排除 AES。這是措辭不足，不是密碼學定律。','The questions only reorder options. A 128-bit block excludes RC4 and 64-bit-block Blowfish, leaving AES and Twofish. The intended nonselected finalist is Twofish, giving D/B. But without an explicit “not selected” condition, AES cannot strictly be excluded. This is incomplete wording, not a cryptographic law.')
 b.p('真正應記住：AES 與 Twofish 都採 128-bit 區塊、都可使用 256-bit 金鑰；Twofish 是決選者，Rijndael 是獲選設計。','Retain the actual facts: AES and Twofish both use 128-bit blocks and support 256-bit keys; Twofish was a finalist and Rijndael was selected.')
 return b.text

def storage(Body):
 b=Body()
 b.p('對應第 20 題 EC-Q024。難點是區分靜態儲存保護與主機已遭入侵時的防護能力。','Reference 20, EC-Q024. Distinguish protection of stored data from protection after a running host is compromised.')
 b.h('p3-disk','1. Disk、Partition、File','1. Disk, partition and file')
 b.p('想像 1 TB SSD 存 Windows、資料庫、照片與文件。Disk 是實際或邏輯儲存裝置，Partition 是其劃分區域，File 是其中資料；像整棟大樓、各樓層與房間文件。','Imagine a 1 TB SSD holding Windows, databases, photos and documents. A disk is a physical or logical storage device, a partition is a divided region and files hold data. The analogy is a whole building, its floors and documents in rooms.')
 b.h('p3-storage-types','2. 三種儲存加密與掛載／解鎖','2. Three storage-encryption scopes and mounting/unlocking')
 b.table([['方式','範圍','例子'],['File Encryption','單一檔案','只加密 patient-list.xlsx'],['Volume Encryption','磁碟區或容器','掛載後像一般磁碟'],['Full Disk Encryption（FDE）','整個磁碟或系統儲存範圍','實際範圍依產品與設定']],
         [['Approach','Scope','Example'],['File encryption','Individual file','Encrypt only patient-list.xlsx'],['Volume encryption','Volume or container','Use it like a disk after mounting'],['Full disk encryption (FDE)','Whole-disk or system-storage scope','Actual protected regions depend on product and configuration']])
 b.p('妥善加密的筆電關機後遺失，可降低拆 SSD 離線讀取資料的風險，這是 Encryption at Rest（靜態資料加密）。但登入後開檔，系統就需提供明文。Mounted Volume 指已接入檔案系統路徑；Unlocked Volume 指已有解密金鑰可用，兩者相關但不同，加密磁碟通常先解鎖才能正常存取。','If a properly encrypted laptop is lost while shut down, encryption at rest can reduce the risk of reading its removed SSD offline. After login and opening a file, however, plaintext must become available. Mounted means attached to a filesystem path; unlocked means the keys needed for decryption are available. These related states are distinct; encrypted volumes generally need unlocking for ordinary access.')
 b.h('p3-veracrypt','3. VeraCrypt 與 Hidden Volume','3. VeraCrypt and hidden volumes')
 b.p('VeraCrypt 可建加密容器，也支援分割區等儲存裝置加密。假設外層容器看起來有 100 GB，可在外層可用空間建立另一密碼的 Hidden Volume（隱藏磁碟區）。外層存一般加密資料，內層存希望額外隱藏的資料；這是包含關係，不是兩個先後磁碟，也不表示真實配置比例。','VeraCrypt creates encrypted containers and supports encryption of partitions and other supported storage. An outer container appearing to hold 100 GB can contain a hidden volume in its free space under another password. Ordinary encrypted data belongs in the outer volume; additional concealed data belongs in the hidden one. This is containment, not two consecutive disks or a proportional layout.')
 b.p('Plausible Deniability（合理否認性）希望在特定條件下，僅由容器外觀難以證明另有隱藏區。它不是永不發現保證：若對手反覆取得不同時間的磁碟快照，可能從變更線索推論；仍須遵循產品安全前提。官方亦要求不要把隱藏磁碟區存於使用耗損平均的裝置，例如 SSD；這個包含關係例子不是此類裝置的配置建議。','Plausible deniability aims to make an additional hidden region difficult to demonstrate from the container’s appearance under specified conditions. It is not a guarantee of permanent concealment: repeated disk snapshots can expose change patterns. The product’s security requirements still apply. They also prohibit storing hidden volumes on wear-leveling devices such as SSDs; this containment example is not a configuration recommendation for those devices.')
 b.h('p3-compromised-host','4. 為何加密不能直接阻止已入侵主機外洩？','4. Why encryption alone does not stop exfiltration from a compromised host')
 b.table([['情境','磁碟狀態','保護界線'],['遺失筆電','關機、未解鎖','降低離線讀取風險'],['伺服器遭入侵','已解鎖，攻擊者有足夠讀取權限','磁碟加密無法單獨阻止明文存取']],
         [['Scenario','Disk state','Protection boundary'],['Lost laptop','Shut down and locked','Reduces offline-reading risk'],['Compromised server','Unlocked, attacker has sufficient read permissions','Disk encryption alone does not stop plaintext access']])
 b.p('合法應用讀檔時，某環節必須解密；有足夠權限的攻擊者可沿相同路徑讀明文。VeraCrypt 官方也指出磁碟加密不是記憶體加密，已開啟檔案明文與必要金鑰可能在 RAM。這是威脅模型差異，不是某產品獨有問題。','An application must decrypt data somewhere to read it. An attacker with sufficient privileges may use the same access path. VeraCrypt documents that disk encryption is not memory encryption; opened-file plaintext and necessary key material may be in RAM. This is a threat-model distinction, not unique to one product.')
 b.p('Threat Model 先定義對手、能力與能接觸的資料，再評估防護。實際應變應依程序控制存取、阻止外洩並保全證據，不是在受入侵主機貿然大量加密。','A threat model defines the adversary, capabilities and accessible data before evaluating protection. Response should follow procedures to control access, stop exfiltration and preserve evidence rather than blindly performing bulk encryption on the compromised host.')
 b.h('p3-q20','5. 第 20 題：功能辨識與實務限制同時保留','5. Reference 20: distinguish product features and operational limits')
 b.p('選項含 BitLocker、FileVault、Rohos、VeraCrypt。BitLocker 是 Windows 磁碟加密，FileVault 是 macOS 磁碟資料保護；Rohos 也有加密儲存與隱藏分割區功能，不能只憑「隱藏」就排除。題幹整組特徵，特別是外層容器內以不同密碼建立 Hidden Volume，最指向 D. VeraCrypt。','Options include BitLocker, FileVault, Rohos and VeraCrypt. BitLocker is Windows disk encryption and FileVault protects macOS disk data. Rohos also offers encrypted storage and hidden-partition features, so “hidden” alone does not exclude it. The combined clues, particularly a hidden volume inside an outer container under a separate password, best point to D, VeraCrypt.')
 b.p('考試辨識功能時可選 D；題幹若暗示加密已掛載磁碟就立即阻止已入侵主機讀病歷，實務結論不成立。','D is the supplied exam expectation, but any suggestion that encrypting a mounted volume immediately prevents an intruder from reading medical records is not an adequate operational conclusion.')
 b.h('p3-modes','6. 同一 AES，不同運作模式','6. The same AES, different modes')
 b.p('引擎相同可用在不同機器：AES 是核心，Mode of Operation 規定長資料或特定場景的用法。XTS-AES 常用儲存保密，AES-GCM 在正確使用下提供加密與完整性驗證。NIST SP 800-38E 明示 XTS-AES 本身不提供資料認證；不能說用了 AES 就同時保證不被偷看與竄改。','The same engine can power different machines. AES is the core cipher; its mode defines use for longer data or a particular setting. XTS-AES commonly protects storage confidentiality, while correctly used AES-GCM provides encryption and integrity verification. NIST SP 800-38E states that XTS-AES itself does not authenticate data. Using AES alone does not establish both confidentiality and tamper detection.')
 return b.text

def asymmetric(Body):
 b=Body()
 b.h('p3-key-distribution','1. 對稱加密遇到的困難','1. The distribution problem for symmetric encryption')
 b.p('對應第 22、23 題並連到 24–27。Alice、Bob 未見過面，若用 AES 傳合約，Bob 仍需正確秘密金鑰；不安全管道直接傳送可能被攔截，這是 Key Distribution Problem。','References 22 and 23 also connect to 24–27. If Alice and Bob have never met and use AES for a contract, Bob still needs the secret key. Sending it directly through an insecure channel risks interception: the key-distribution problem.')
 b.h('p3-key-pair','2. 公鑰與私鑰的關係','2. The public/private key relationship')
 b.p('Asymmetric Cryptography 使用依演算法建立、有數學關係的 Key Pair（金鑰對）：Public Key 可公開，Private Key 須保護。對支援公鑰加密的方案，寄件者無須先與每位收件者共享同一秘密。','Asymmetric cryptography uses an algorithm-specific, mathematically related key pair. The public key can be shared and the private key must be protected. Public-key encryption schemes let a sender communicate without first sharing the same secret with every recipient.')
 b.table([['Alice 寄機密文件給 Bob','條件'],['取得 Bob 公鑰','公鑰可公開，但身分必須可信'],['用 Bob 公鑰加密','傳送密文'],['Bob 用自己的私鑰解密','Alice 不需要 Bob 私鑰']],
         [['Alice sends Bob a confidential document','Condition'],['Obtain Bob’s public key','It can be public but its identity must be trusted'],['Encrypt with Bob’s public key','Transmit ciphertext'],['Bob decrypts with his private key','Alice never needs Bob’s private key']])
 b.p('非對稱不等於都能加密檔案：RSA 有加密與簽章方案，DSA 主要做簽章，Diffie–Hellman 做金鑰協議。','Asymmetric does not mean every algorithm encrypts files: RSA has encryption and signature schemes, DSA mainly signs and Diffie–Hellman establishes keys.')
 b.h('p3-rsa','3. RSA 的不同安全方案','3. Different RSA schemes')
 b.p('RSA 取自 Rivest、Shamir、Adleman，是公鑰密碼系統；主要數學背景涉及大整數模運算與整數分解相關困難性。先理解金鑰數學關係能支援多種方案，不必先推導所有數學。','RSA takes its name from Rivest, Shamir and Adleman. It is a public-key cryptosystem involving large-integer modular arithmetic and hardness related to factoring. Its related keys support different schemes; understanding their roles comes before a full mathematical derivation.')
 b.table([['方案','功能'],['RSAES-OAEP','公鑰加密、私鑰解密'],['RSASSA-PSS','私鑰簽章、公鑰驗證']],
         [['Scheme','Function'],['RSAES-OAEP','Public-key encryption and private-key decryption'],['RSASSA-PSS','Private-key signing and public-key verification']])
 b.p('RFC 8017 分別規範這些方案，不是把公私鑰運算方向對調就能安全完成所有功能。第 23 題 P3-Q056 問非對稱加密，選項 A AES、B DES、C RSA、D Blowfish；其餘皆對稱演算法，供稿答案 C. RSA。','RFC 8017 specifies these as separate schemes. Reversing the direction of public/private operations does not securely implement every function. Reference 23, P3-Q056, asks for an asymmetric encryption algorithm among A AES, B DES, C RSA and D Blowfish. The others are symmetric, so the supplied answer is C, RSA.')
 b.h('p3-dh','4. Diffie–Hellman：公開交換仍可建立秘密','4. Diffie–Hellman: establishing a secret through public exchange')
 b.p('DH 是 Key Agreement。安全條件成立時，雙方公開交換資訊，各自算同一秘密，並不直接傳它。顏色類比：共同公開基底，各自混入秘密顏色，交換混合結果後再用保留秘密做可交換順序的混合，得到相同結果。真正 DH 用群運算，不是物理顏料。','DH is key agreement. Under suitable security conditions, parties publicly exchange information and independently compute the same secret without directly sending it. A color analogy uses a public base, private colors, exchanged mixtures and a further order-independent mixing step. Actual DH uses mathematical group operations, not physical paint.')
 b.h('p3-dh-example','5. 用小數字核對 DH','5. Check DH with small numbers')
 b.p('以下刻意使用不安全小參數，只作數學示範。公開 p = 23、g = 5；p 是模數質數，g 是指定群的生成元或基底。mod 是取餘數，例如 29 mod 23 = 6。Alice 秘密 a = 6，Bob 秘密 b = 15。','The deliberately tiny parameters below are insecure and only illustrate the mathematics. Public values are p = 23 and g = 5: p is the prime modulus, and g is the group generator or base. Mod means remainder, for example 29 mod 23 = 6. Alice’s secret is a = 6 and Bob’s is b = 15.')
 b.table([['角色','公開值','收到對方值','共同秘密計算'],['Alice','A = 5^6 mod 23 = 8','B = 19','K_A = 19^6 mod 23 = 2'],['Bob','B = 5^15 mod 23 = 19','A = 8','K_B = 8^15 mod 23 = 2']],
         [['Party','Public value','Received value','Shared-secret calculation'],['Alice','A = 5^6 mod 23 = 8','B = 19','K_A = 19^6 mod 23 = 2'],['Bob','B = 5^15 mod 23 = 19','A = 8','K_B = 8^15 mod 23 = 2']])
 b.p('Alice 未把 a 傳給 Bob，Bob 未把 b 傳給 Alice，卻都得到 K = 2。真實協定需要安全參數、驗證與 KDF；不能拿此玩具例子的參數保護資料。','Alice does not send a, and Bob does not send b, yet both obtain K = 2. Real protocols require secure parameters, validation and a KDF. These toy parameters must not protect actual data.')
 b.h('p3-mitm','6. 能旁聽公開值，與能替換公開值不同','6. Observing public values differs from replacing them')
 b.p('公開值當然可以被攔截；安全參數與假設下，僅靠它們難以可行地算出秘密。但主動攻擊者 Eve 可替換公開值：Alice 以為對方是 Bob，Bob 以為對方是 Alice，Eve 卻分別與兩人建立不同秘密，攔截後再加密轉送。這是 MITM（中間人攻擊）。','Public values can be intercepted. Under secure parameters and assumptions, observing them alone should not feasibly reveal the secret. An active Eve can instead replace them: Alice thinks she is talking to Bob, Bob thinks he is talking to Alice, while Eve establishes different secrets with each and decrypts/re-encrypts relayed traffic. This is a man-in-the-middle attack.')
 b.p('DH 必須搭配身分驗證，才能處理這類攻擊；「建立秘密」不等於「知道正在和誰建立秘密」。','DH requires authentication to address that attack. Establishing a secret does not establish who shares it with you.')
 b.h('p3-hybrid-tls','7. HTTPS 的混合式分工','7. Hybrid cryptography in HTTPS')
 b.p('以憑證驗證伺服器、使用 ECDHE 的 TLS 1.3 為例，下表依原稿概念流程保留成功與失敗分支，不當成逐封包時序。','For certificate-authenticated TLS 1.3 using ECDHE, this table preserves the source’s conceptual success/failure branches, not a packet-by-packet timeline.')
 b.table([['概念節點','動作／條件'],['瀏覽器連銀行','開始連線'],['ECDHE','建立共同秘密'],['憑證與交握簽章','驗證伺服器身分'],['身分驗證失敗','拒絕可信連線'],['身分驗證成功','依金鑰排程以 HKDF 導出適用流量金鑰'],['AEAD','AES-GCM 等保護資料']],
         [['Conceptual node','Action / condition'],['Browser connects to bank','Begin connection'],['ECDHE','Establish shared secret material'],['Certificate and handshake signature','Authenticate the server'],['Authentication fails','Reject the trusted connection'],['Authentication succeeds','Derive suitable traffic keys through the HKDF-based key schedule'],['AEAD','Protect data with a scheme such as AES-GCM']])
 b.p('TLS 是保護網路通訊的協定；ECDHE 用暫時性秘密與橢圓曲線；HKDF（HMAC-based Key Derivation Function）由秘密材料導出不同用途金鑰；AEAD 同時加密並驗證完整性與指定附加資料。這是 Hybrid Cryptosystem：公鑰機制協助建鍵，高效率對稱機制保護大量資料。TLS 1.3 也支援 PSK 等配置；現行 RFC 9846 取代供稿第 3 份仍引用的 RFC 8446。','TLS protects network communication; ECDHE uses ephemeral secrets and elliptic curves; HKDF, HMAC-based key derivation function, derives purpose-specific keys; AEAD encrypts and authenticates integrity and specified associated data. This hybrid cryptosystem uses public-key mechanisms for establishment and efficient symmetric mechanisms for bulk traffic. TLS 1.3 also supports configurations such as PSK. Current RFC 9846 replaces RFC 8446, which this third source still cited.')
 b.h('p3-q22','8. 第 22 題 EC-Q053','8. Reference 22, EC-Q053')
 b.p('供稿答案 D. Asymmetric encryption。Disk Encryption 保護儲存，Symmetric Encryption 不會自動解決首次共享秘密，Hash Functions 不能單獨完成安全建鍵。更精確稱 Public-Key Key Establishment，包含傳送、協議或封裝，不宜全部混稱非對稱加密。','The supplied answer is D, Asymmetric encryption. Disk encryption protects storage, symmetric encryption does not automatically establish an initial shared secret, and hash functions alone do not securely establish keys. Public-key key establishment is more precise and includes transport, agreement or encapsulation rather than calling all of them asymmetric encryption.')
 return b.text

def signatures(Body):
 b=Body()
 b.p('對應第 24–27 題。Encryption 防偷看，Hash 產生資料指紋，Signature 產生可由公鑰驗證的私鑰簽署證據，先分清任務。','References 24–27. Encryption prevents reading, hashes produce fingerprints and signatures provide private-key signing evidence verifiable with a public key. Distinguish the jobs first.')
 b.h('p3-hash','1. Hash 與文件指紋','1. Hashes and document fingerprints')
 b.p('交易文件「付款 NT$100,000 給廠商 A」經 SHA-256 產生 256-bit Digest（Hash Value）；這是固定長度摘要，流程未提供實算值。若被改成 NT$1,000,000，通常摘要會大幅不同，稱 Avalanche Effect（雪崩效應）。Hash 不是 Encryption，沒有持金鑰解密回原文的用途；不同輸入仍可能碰撞，安全性要求難以找到可利用碰撞。','The transaction “Pay NT$100,000 to supplier A” produces a 256-bit SHA-256 digest, or hash value. This is a fixed-length fingerprint; no computed value was supplied. Changing it to NT$1,000,000 usually changes the digest substantially, illustrating the avalanche effect. Hashing is not encryption and has no key-based decryption purpose. Collisions still exist; security requires exploitable collisions to be difficult to find.')
 b.h('p3-unprotected-hash','2. 文件與 Hash 一起被換掉','2. Replacing both document and digest')
 b.p('攻擊者改交易金額，再附自己重算的 Hash，接收者比對仍一致。這只證明文件與所附摘要相符，不能單靠未保護摘要證明來源為銀行，需適當 Signature 或 MAC（Message Authentication Code，訊息認證碼）。','An attacker changes the amount and supplies a newly calculated hash. A receiver can still find a match. That proves consistency with the accompanying digest, not a bank origin. Appropriate signatures or MACs, message authentication codes, provide authentication mechanisms.')
 b.h('p3-signing-flow','3. 簽署與驗證的完整概念流程','3. The conceptual signing and verification flows')
 b.table([['簽署步驟','資料與動作'],['1','交易資料 M'],['2','計算 Hash'],['3','取得摘要 H(M)'],['4','以銀行私鑰與簽章方案處理'],['5','產生 Signature'],['6','傳送 M + Signature']],
         [['Signing step','Data / action'],['1','Transaction data M'],['2','Calculate hash'],['3','Obtain H(M)'],['4','Apply the bank private key and signature scheme'],['5','Produce the signature'],['6','Send M + signature']])
 b.table([['驗證節點','條件與結果'],['收到 M 與 S','開始驗證'],['確認銀行公鑰可信身分','不能只接受不明目錄'],['用公鑰與指定方案驗 M、S','取得驗證結果'],['未通過','簽章無效，不能採信'],['通過','取得簽章與資料完整性的密碼學證據'],['通過後仍須','檢查交易授權、時效與業務規則']],
         [['Verification node','Condition / result'],['Receive M and S','Begin validation'],['Establish the bank public key’s trusted identity','An unknown directory is insufficient'],['Verify M and S with the public key and specified scheme','Obtain a verification result'],['Failure','Invalid signature; do not rely on it'],['Success','Cryptographic evidence concerning the signature and integrity'],['After success','Still check transaction authorization, freshness and business rules']])
 b.p('上表把原稿流程圖轉成可重排 HTML，保留兩個條件分支；不是把摘要用私鑰「加密」的通用說法。RSA-PSS 有編碼程序，DSA／ECDSA 有自己的方程式；此處呈現共同概念。','The reflowable HTML tables preserve the source flowcharts’ conditional branches. This is not generically encrypting a digest with a private key. RSA-PSS uses an encoding procedure and DSA/ECDSA use their own equations; the tables describe shared concepts.')
 b.h('p3-signature-properties','4. 三個性質與不可否認性的條件','4. Three properties and conditions for non-repudiation')
 b.table([['性質','中文','例子'],['Integrity','完整性','簽署後金額有無被改？'],['Authentication','來源認證','簽章是否對應銀行可信金鑰？'],['Non-repudiation','不可否認性','能否提出具歸屬證據，支持某方簽署？']],
         [['Property','Meaning','Example'],['Integrity','Protection against improper changes','Was the signed amount modified?'],['Authentication','Origin authentication','Does the signature verify under the bank’s trusted key?'],['Non-repudiation','Attributable signing evidence','Is there evidence supporting that a party signed?']])
 b.p('NIST FIPS 186-5 支持這些簽章用途。但私鑰被偷、簽署系統被控制或授權程序有缺陷仍可產生爭議；不是驗證通過就絕對不能否認。','NIST FIPS 186-5 supports these signature uses. Stolen private keys, a compromised signing system or flawed authorization can still cause disputes. Successful verification is not an unconditional bar to denial.')
 b.table([['相關機制','職責'],['PKI','管理憑證、公鑰與信任關係'],['Digital Certificate','將公鑰與身分或屬性連結的簽署資料'],['CA','依規則核發與管理憑證'],['HSM','保護金鑰並執行密碼運算的安全硬體'],['Audit Log','記錄人、時間、程序與操作的證據']],
         [['Supporting mechanism','Responsibility'],['PKI','Manage certificates, public keys and trust relationships'],['Digital certificate','Signed information binding a key to identity or attributes'],['CA','Issue and manage certificates under policy'],['HSM','Security hardware protecting keys and performing cryptographic operations'],['Audit log','Evidence of who acted, when and through which procedure']])
 b.h('p3-signature-limits','5. 第 26 題：簽章不保證保密與可用','5. Reference 26: signatures do not guarantee confidentiality or availability')
 b.p('銀行寄出已簽交易文件，取得文件與簽章的人仍可能閱讀原文，因簽章未把文件變密文。防偷看用加密，驗來源與完整性用適當簽章；兩者都需要時，適當組合。簽章也不能保證伺服器不當機或網路不中斷。','Anyone obtaining a signed bank document and its signature may still read the original because signing does not encrypt the document. Use encryption against reading and an appropriate signature for origin/integrity evidence; combine mechanisms where both goals matter. A signature also cannot keep a server running or a network connected.')
 b.p('第 26 題 P3-Q071 供稿答案 B. Integrity, Non-repudiation, and Authentication。Confidentiality、Availability、Privacy、Speed 等選項不是簽章直接提供的完整安全性質組合。','Reference 26, P3-Q071, has supplied answer B, Integrity, Non-repudiation, and Authentication. Combinations involving confidentiality, availability, privacy or speed do not describe the direct set of signature properties being asked for.')
 return b.text

def algorithms(Body):
 b=Body()
 b.p('對應第 24、25、27 題。RSA、DSA、DH、ElGamal 都涉及公鑰密碼學，但須用用途與具區辨力的特徵辨認。','References 24, 25 and 27. RSA, DSA, DH and ElGamal are related to public-key cryptography but differ in purpose and distinguishing features.')
 b.h('p3-four-algorithms','1. 四種技術的比較','1. Compare four techniques')
 b.table([['技術','先想到','功能'],['RSA','公鑰系統、整數分解相關困難、模冪','加密、簽章與特定金鑰建立方案'],['DSA','數位簽章、每訊息秘密 k','簽章'],['Diffie–Hellman','建立共同秘密','金鑰協議'],['ElGamal','離散對數與隨機秘密值','相關加密／簽章方案']],
         [['Technique','Association','Function'],['RSA','Public-key system, factoring-related hardness, modular exponentiation','Encryption, signatures and specific key-establishment schemes'],['DSA','Digital signature and per-message secret k','Signatures'],['Diffie–Hellman','Establish a common secret','Key agreement'],['ElGamal','Discrete logarithms and random secret material','Related encryption/signature schemes']])
 b.p('RSA、DSA 與 ElGamal 都可能用模運算或模冪。只寫 modular arithmetic 不足唯一識別 RSA。','RSA, DSA and ElGamal can all involve modular arithmetic or exponentiation. Modular arithmetic alone does not uniquely identify RSA.')
 b.h('p3-dsa-parameters','2. DSA 的每訊息秘密與公開域參數','2. DSA per-message secrets and public domain parameters')
 b.p('DSA 是 Digital Signature Algorithm。傳統簽署除了永久私鑰，還需每訊息秘密 k（Per-message Secret Number，可視為此運算的 Nonce）。這份額外秘密材料若處理不當，可能暴露永久私鑰。結果為簽章二元組 (r,s)，由摘要、私鑰、k 與公開參數計算。','DSA means digital signature algorithm. Traditional signing requires a per-message secret number k, used as a nonce in this operation, in addition to the long-term private key. Mishandling that extra secret can expose the permanent key. The resulting pair (r,s) depends on the digest, private key, k and public parameters.')
 b.table([['參數','意義'],['p','有限域的質數模數'],['q','相關子群的質數階'],['g','子群生成元']],
         [['Parameter','Meaning'],['p','Prime modulus for the finite field'],['q','Prime order of the relevant subgroup'],['g','Subgroup generator']])
 b.p('Public Domain Parameters 的 Domain 是數學運算環境，不是網域名稱，也不是 DNS。','Domain in public domain parameters identifies the mathematical setting, not an Internet domain name or DNS.')
 b.h('p3-dsa-k','3. 為何不能不安全地重用 k？','3. Why is unsafe reuse of k dangerous?')
 b.p('簡化核心關係：s = k^(-1) × (H(m) + x r) mod q。H(m) 是摘要，x 是私鑰，k 是該次秘密，r、s 是簽章值，q 是子群階；此處略去摘要截取等細節。','A simplified core relation is s = k^(-1) × (H(m) + x r) mod q. H(m) is the digest, x the private key, k the per-message secret, r and s signature values and q the subgroup order. Details such as digest truncation are omitted here.')
 b.p('k^(-1) 是模 q 的乘法反元素，不是一般浮點除法。不同文件若不安全地用相同 k，公開簽章可能形成可解出 x 的關係。因此永久私鑰與簽章過程秘密材料都要保護，隨機數產生器亦重要。','k^(-1) is the multiplicative inverse modulo q, not ordinary floating-point division. Unsafe reuse of k for different documents can expose relationships in public signatures that reveal x. Protect both long-term keys and signing secrets; the random-number generator also matters.')
 b.p('RFC 6979 的 Deterministic DSA／ECDSA 可依私鑰與摘要確定性推導合適 k，不必每次取得新外部隨機輸入；這不同於對不同訊息意外重用不安全 k。','RFC 6979 describes deterministic DSA/ECDSA, deriving a suitable k from the key and digest without fresh external random input each time. That differs from accidentally reusing an unsafe k across different messages.')
 b.h('p3-dsa-modern','4. 現代標準中的 DSA','4. DSA in the modern standard')
 b.p('NIST FIPS 186-5 在 2023 年發布，不再核准 DSA 產生新簽章，只保留驗證標準實施日前產生的簽章。新簽章技術含 RSA、ECDSA、EdDSA。考題可依傳統 DSA 特徵作答，但新設計若受該標準約束，不能把舊式 DSA 當預設。','NIST FIPS 186-5, published in 2023, no longer approves DSA for signature generation and retains verification of signatures generated before the standard’s implementation date. Generation techniques include RSA, ECDSA and EdDSA. Recognize traditional DSA in exam scenarios without making it the default for new designs subject to that standard.')
 b.h('p3-q24','5. 第 24 題 P1-Q085','5. Reference 24, P1-Q085')
 b.p('線索是每次新隨機值、公開群與子群模運算、公鑰驗證。傳統 DSA 最符合預期，供稿答案 C. DSA。RSA 也能簽，但此組參數與 k 更指向 DSA；DH 主要為金鑰協議。ElGamal 簽章也用一次性秘密並有共同數學特徵，原題仍有歧義，不把單一線索當定律。','Fresh random signing values, public group/subgroup parameters and public-key verification most strongly suggest traditional DSA, the supplied answer C. RSA signs too, but these parameters and k point more toward DSA; DH primarily agrees keys. ElGamal signatures also use per-message secrets and share mathematical features, so the wording retains ambiguity rather than giving a universal identification rule.')
 b.h('p3-q25','6. 第 25 題 P2-Q034','6. Reference 25, P2-Q034')
 b.p('計算交易 Hash、私鑰簽署、公鑰驗證不能單獨辨認 RSA，DSA 也有這個概念流程。額外線索是同一演算法家族支援加密、簽章與金鑰建立，因此供稿答案 A. RSA；NIST SP 800-56B Rev. 2 包含 RSA-based 傳送與協議方案。','Hashing a transaction, signing privately and verifying publicly do not alone identify RSA; DSA has that conceptual flow too. The additional clue is one family supporting encryption, signatures and key establishment. The supplied answer is A, RSA. NIST SP 800-56B Rev. 2 includes RSA-based transport and agreement schemes.')
 b.p('多種用途必須區分具體安全方案，不表示同一組金鑰應全部兼用；FIPS 186-5 對 RSA 簽章金鑰用途有隔離要求。TLS 1.3 也已移除傳統 Static RSA Key Exchange。','Different purposes require distinct secure schemes; they do not justify using one key pair for everything. FIPS 186-5 restricts reuse of RSA signing keys for other purposes. TLS 1.3 also removed traditional static RSA key exchange.')
 b.h('p3-q27','7. 第 27 題 EC-Q084：公鑰目錄的信任','7. Reference 27, EC-Q084: trust in a public-key directory')
 b.p('私鑰簽署、公鑰驗證與模冪不能唯一識別 RSA，DSA／ElGamal 類方案也部分符合；B. RSA 是供稿題庫預期。更重要的是：驗證所用公鑰真屬銀行嗎？','Private signing, public verification and modular exponentiation do not uniquely identify RSA; DSA/ElGamal-related schemes share some features. B, RSA is the supplied expected answer. The more important question is whether the verification key really belongs to the bank.')
 b.p('若攻擊者可改公鑰目錄，就能建自己的金鑰、簽假交易、以自己的公鑰冒充銀行。數學驗證可能成功，卻錯把結果當銀行授權。PKI 與可信金鑰綁定要處理這個問題。','An attacker controlling a directory can generate keys, sign a fake transaction and substitute their public key for the bank’s. Mathematical verification may pass while bank authorization is falsely inferred. PKI and trusted key binding address this problem.')
 b.table([['判斷','實際證據'],['Signature Valid','指定公鑰下的數學簽章驗證通過'],['Signer Identity Verified','可信程序確認公鑰與預期身分正確綁定']],
         [['Judgment','Actual evidence'],['Signature valid','Mathematical verification succeeds under the specified public key'],['Signer identity verified','A trusted procedure confirms binding to the expected identity']])
 b.p('前者不自動保證後者，兩者也不自動取代交易授權、時效與業務規則檢查。','The first does not automatically establish the second; neither replaces transaction authorization, freshness or business-rule checks.')
 return b.text

def integration(Body):
 b=Body()
 b.h('p3-method','1. 五步解題法','1. Five-step reasoning method')
 b.listing(['1. 題目要保護什麼：保密、建鍵、完整性或身分驗證？','2. 辨認所需密碼學技術類別。','3. 找最有區辨力的技術線索。','4. 排除功能不符的選項。','5. 檢查答案是否真的唯一，再作答並辨認簡化或歧義。'],['1. Identify the goal: confidentiality, key establishment, integrity or authentication.','2. Identify the required cryptographic category.','3. Find the most discriminating technical clues.','4. Exclude options with incompatible functions.','5. Check uniqueness, answer and recognize simplification or ambiguity.'])
 b.p('例如 fresh random value for each signature：先辨認簽章，不是磁碟或一般加密；再比較需要每訊息秘密的 DSA 與 ElGamal，找更具體特徵，最後選最符合題意者，而不是只背一個關鍵字。','For fresh random value for each signature, first identify signing rather than disk or ordinary encryption. Compare DSA and ElGamal-style per-message secrets, seek more specific evidence and choose the best fit rather than memorizing one keyword.')
 b.h('p3-nine-answers','2. 九題完整判斷表','2. Complete nine-reference reasoning table')
 rows=[['19｜EC-Q493','D. Twofish','AES 決選者，但題幹未充分排除 AES','An AES finalist, but the wording does not adequately exclude AES'],['20｜EC-Q024','D. VeraCrypt','外層容器與 Hidden Volume；不自動阻止入侵中外洩','Outer container and hidden volume; not a cure for active exfiltration'],['21｜P1-Q114','B. Twofish','同第 19 題，選項換序','Same concept as reference 19 with reordered options'],['22｜EC-Q053','D. Asymmetric encryption','公鑰機制支援建鍵，仍需認證','Public-key mechanisms support key establishment with authentication'],['23｜P3-Q056','C. RSA','四項中公鑰密碼演算法','The public-key algorithm among the four'],['24｜P1-Q085','C. DSA','公開參數與每訊息秘密 k，題幹仍須注意歧義','Public parameters and per-message k, with ambiguity caveats'],['25｜P2-Q034','A. RSA','不同方案支援多用途，不兼用同組金鑰','Different schemes support different jobs; not unrestricted key reuse'],['26｜P3-Q071','B','完整性、來源認證、有條件不可否認性','Integrity, origin authentication and conditional non-repudiation'],['27｜EC-Q084','B. RSA','題庫預期；模冪與私鑰簽署不足唯一識別','Expected key; exponentiation and private signing are not unique identifiers']]
 b.table([['題號','供稿答案','必須理解的理由']]+[[r[0],r[1],r[2]] for r in rows],[['Reference','Supplied answer','Reason to understand']]+[[r[0],r[1],r[3]] for r in rows])
 b.h('p3-ten-terms','3. 十個核心名詞','3. Ten core terms')
 terms=[['Symmetric Encryption','共同秘密金鑰保護資料','Protect data with shared secret key material'],['Asymmetric Cryptography','依公／私鑰數學關係完成指定功能','Use related public/private keys for specified functions'],['Block Cipher','固定長度區塊轉換','Transform fixed-size blocks'],['Stream Cipher','產生金鑰串流並結合資料','Generate a keystream and combine it with data'],['Key Exchange / Establishment','建立或取得共同秘密','Establish or obtain shared secret material'],['Hash Function','任意允許長度映射為固定摘要','Map allowed-length inputs to a fixed-length digest'],['Digital Signature','私鑰產生、公鑰驗證的簽署證據','Private-key signing evidence verified publicly'],['Nonce','特定操作範圍的唯一性等要求依協定定義','A value whose required uniqueness and other properties depend on the protocol'],['Modular Exponentiation','次方後取模餘數','Exponentiation modulo a specified number'],['Public Key Authentication','驗證公鑰與預期身分的可信綁定','Authenticate the binding of a public key to the expected identity']]
 b.table([['名詞','白話意義']]+[[r[0],r[1]] for r in terms],[['Term','Plain-language meaning']]+[[r[0],r[2]] for r in terms])
 b.p('仍不清楚時，回看銀行、保險箱、磁碟區與 DH 小例子，再自行解釋每個名詞的用途與界線。','If a term remains unclear, revisit the bank, safe, volume and DH examples, then explain its purpose and limitations in your own words.')
 return b.text

def recall(Body):
 b=Body()
 b.p('六個供稿問題先想再展開；答案依完整正文補成，屬編輯參考解析。','Think through these six supplied prompts before revealing the answers, which are editorial explanations based on the body.')
 cards=[('為什麼 128-bit Block + 256-bit Key 不能唯一識別 Twofish？','Why do a 128-bit block and 256-bit key not uniquely identify Twofish?','19、21','AES 也符合；需要額外區辨條件，且「AES 決選者」也包含獲選的 Rijndael。','AES matches too. Additional discriminating conditions are needed, and AES finalists also include selected Rijndael.'),('全磁碟加密為何仍可能讓攻擊者讀病患資料？','Why can an attacker still read patient data despite full-disk encryption?','20','磁碟已解鎖且攻擊者有權限時，可沿應用讀取路徑取得明文；靜態加密不是入侵清除。','An unlocked disk and sufficient privileges can expose plaintext through application access. At-rest encryption is not intrusion removal.'),('DH 能建秘密，為何仍有中間人風險？','Why can DH still suffer a man-in-the-middle attack?','22','若不驗證公開值的來源，對手可替換並分別與兩端建秘密。','Without authenticating the source of public values, an attacker can replace them and establish separate secrets with each endpoint.'),('單獨 SHA-256 為何不能證明交易來自銀行？','Why can SHA-256 alone not prove a bank origin?','25、26','誰都能對假交易重算摘要；需可信公鑰簽章或合適認證機制與身分綁定。','Anyone can hash a fake transaction. Use a suitable authenticated mechanism and trusted identity/key binding.'),('DSA 的 k 為何不能在不同訊息不安全重用？','Why must DSA not unsafely reuse k across messages?','24','重用可暴露足以推回私鑰的數學關係；可用安全隨機來源或適當確定性方案，並遵循現代演算法標準。','Reuse can expose relationships revealing the private key. Use suitable secure randomness or deterministic schemes and follow current algorithm requirements.'),('RSA 驗證成功為何不等於真正銀行授權？','Why does successful RSA verification not prove actual bank authorization?','27','驗證公鑰可能被冒換；即使可信綁定正確，還須檢查交易權限、時效與業務規則。','The verification key may have been substituted. Even with a trusted binding, check transaction permissions, freshness and business rules.')]
 for lang in ['zh','en']:b.text[lang].append({'kind':'recall','caption':'六張密碼學回憶卡' if lang=='zh' else 'Six cryptography recall cards','description':'先回答原因，再看解析；翻卡或看答案不作學習完成紀錄。' if lang=='zh' else 'Explain the reason before revealing the answer. Viewing cards is not recorded as completed learning.','cards':[{'question':r[0 if lang=='zh' else 1],'references':r[2],'answer':[r[3 if lang=='zh' else 4]]} for r in cards]})
 return b.text

def checks(Body):
 b=Body()
 b.p('保留供稿五題：前三題為四選項，後兩題為開放推理。先獨立回答；選項解析依正文補充，開放題不提供自動評分或外送批改。','The five supplied questions comprise three four-option questions and two open reasoning tasks. Answer independently. Option explanations are editorial additions from the body; open responses are not automatically graded or transmitted.')
 data=[('廠商宣稱 128-bit Block、256-bit Key 一定是 Twofish，你如何判斷？',['A. 正確，只有 Twofish 有這規格','B. 正確，AES 只用 128-bit 金鑰','C. 無法唯一判定，其他演算法也可能符合','D. 應是 RC4，因為它有 128-bit Block'],'A vendor claims a 128-bit block and 256-bit key uniquely identify Twofish. How do you judge?',['A. Correct; only Twofish has those values','B. Correct; AES only has 128-bit keys','C. Not unique; other algorithms can match','D. It is RC4 because RC4 has a 128-bit block'],2,['AES 等也符合。','AES 另有 192／256-bit 金鑰。','規格不足以唯一識別。','RC4 是串流加密。'],['AES also matches.','AES also supports 192/256-bit keys.','These specifications do not uniquely identify the algorithm.','RC4 is a stream cipher.']),('已開機並解鎖的資料庫伺服器遭入侵，對手有病歷讀取權限，何者正確？',['A. 重新加密就自動停止外洩','B. 安裝 Hidden Volume 就清除攻擊者','C. 先處理存取、外洩與證據；磁碟加密不能單獨解決','D. SHA-256 會阻止讀取'],'An attacker can read patient records on a running, unlocked database server. Which statement is correct?',['A. Re-encryption automatically stops disclosure','B. Installing a hidden volume removes the attacker','C. Address access, exfiltration and evidence; disk encryption alone is insufficient','D. SHA-256 prevents reading'],2,['已解鎖主機仍可能提供明文。','隱藏儲存不等於事件清除。','符合威脅模型與應變優先順序。','摘要不提供存取控制或保密。'],['An unlocked host may still expose plaintext.','Hidden storage is not incident eradication.','This respects the threat model and response priorities.','A digest does not control access or provide confidentiality.']),('Alice、Bob 以 DH 建秘密，卻未驗證公開值來自誰，最大問題是？',['A. DH 無法建共同秘密','B. 對手可替換公開值，與雙方建不同秘密','C. 公鑰交換必暴露私鑰','D. 應改 DSA 加密'],'Alice and Bob use DH but do not authenticate public values. What is the main risk?',['A. DH cannot establish a shared secret','B. An attacker substitutes values and establishes separate secrets','C. Exchanging public values necessarily reveals private keys','D. Switch to DSA encryption'],1,['DH 可協議秘密，但仍需認證。','正是中間人攻擊。','安全參數下公開值不等於私鑰。','DSA 是簽章用途，不能取代此認證問題。'],['DH can agree a secret but needs authentication.','This is the man-in-the-middle risk.','Public values are not private keys under secure assumptions.','DSA signing does not replace the missing authentication.'])]
 for lang in ['zh','en']:
  items=[]
  for i,(zp,zo,ep,eo,a,zr,er) in enumerate(data,1):items.append({'id':f'p3-check-{i}','prompt':zp if lang=='zh' else ep,'options':zo if lang=='zh' else eo,'answer':a,'rationales':zr if lang=='zh' else er})
  b.text[lang].append({'kind':'checks','items':items})
 b.h('p3-open-q4','第 4 題｜Hash 與簽章','Question 4 | Hashes and signatures')
 b.p('銀行交易 API 只在交易 JSON 後加 SHA-256，就宣稱證明交易一定來自銀行。缺少什麼？如何改善？請說明可信金鑰、來源認證與完整性證據的角色。','A bank transaction API appends SHA-256 to transaction JSON and claims it proves bank origin. What is missing and how should it improve? Explain trusted keys, origin authentication and integrity evidence.')
 b.h('p3-open-q5','第 5 題｜識別簽章與 k 風險','Question 5 | Identify a signature and the risk to k')
 b.p('系統以公開 p、q、g 與每次秘密 k 產生 (r,s)。團隊因有模冪就斷言 RSA。請說明更符合的演算法、為何不能只看模冪，以及不安全重用 k 的後果。','A system uses public p, q, g and per-message secret k to produce (r,s). The team asserts RSA because modular exponentiation is involved. Explain the better-matching algorithm, why exponentiation alone is insufficient and the consequence of unsafe k reuse.')
 b.h('p3-learning-standard','最終學習驗收標準','Final learning criteria')
 b.table([['層次','供稿建議標準'],['L1 術語','解釋 AES、Twofish、RSA、DSA、DH、Hash、Signature'],['L2 原理','說明金鑰對、協議、磁碟解鎖與簽章運作'],['L3 考題','九題預期答案與主要錯誤選項理由'],['L4 遷移','五個新情境推理正確，含兩題開放題'],['L5 批判','指出線索不足與安全結論的額外條件']],
         [['Level','Suggested criterion'],['L1 Terminology','Explain AES, Twofish, RSA, DSA, DH, hashes and signatures'],['L2 Mechanisms','Explain key pairs, agreement, disk unlocking and signing'],['L3 Questions','Give the nine expected answers and justify major exclusions'],['L4 Transfer','Reason correctly through five new scenarios, including two open questions'],['L5 Critical judgment','Identify insufficient clues and extra conditions for security claims']])
 b.p('L4／L5 是供稿建議的推理能力目標，不是網頁自動認證或官方通過證明。先不翻筆記作答，再由教師或同儕依理由檢視錯誤，針對缺口補強並換題複測。','L4/L5 are the source’s reasoning goals, not automatic page certification or proof of passing an official exam. Answer without notes, have a teacher or peer examine the reasoning, address gaps and retest with different questions.')
 return b.text

def build_part_three(Body):
 specs=[('foundations','第一階段｜密碼學的工作與術語','Stage 1 | Cryptographic jobs and terms',foundations),('symmetric','第二階段｜對稱加密與 AES 選拔','Stage 2 | Symmetric encryption and AES selection',symmetric),('storage','第三階段｜VeraCrypt 與磁碟威脅模型','Stage 3 | VeraCrypt and disk threat models',storage),('asymmetric','第四階段｜公鑰、RSA 與 DH','Stage 4 | Public keys, RSA and DH',asymmetric),('signatures','第五階段｜數位簽章與驗證','Stage 5 | Digital signatures and verification',signatures),('algorithms','第六階段｜RSA、DSA、DH、ElGamal','Stage 6 | RSA, DSA, DH and ElGamal',algorithms),('integration','第七階段｜五步解題與九題整合','Stage 7 | Five-step reasoning and nine references',integration),('recall','第八階段｜六張主動回憶卡','Stage 8 | Six active-recall cards',recall),('checks','第九階段｜情境檢核與學習標準','Stage 9 | Scenario checks and learning criteria',checks)]
 result={'zh':[],'en':[]}
 for id,zh,en,fn in specs:
  body=fn(Body)
  for lang in ['zh','en']:result[lang].append({'id':'p3-'+id,'heading':zh if lang=='zh' else en,'body':body[lang]})
 return result
